package com.example.persistence;

import org.springframework.data.annotation.Id;
import org.springframework.data.mongodb.core.mapping.Document;
import jakarta.persistence.Entity;
import jakarta.persistence.Table;

// SQL Entity: Normalized, enforces strict relational mapping
@Entity
@Table(name = "orders")
class OrderSqlEntity {
    @jakarta.persistence.Id
    private Long id;
    private String customerEmail;
    private java.math.BigDecimal totalAmount;
}

// NoSQL Document: Denormalized, embeds related state for high-speed writes
@Document(collection = "orders")
class OrderNoSqlDocument {
    @Id
    private String id;
    private String customerEmail;
    private java.math.BigDecimal totalAmount;
    private java.util.List<LineItem> items;

    public static class LineItem {
        private String sku;
        private int quantity;
        private java.math.BigDecimal price;
    }
}
